"  const handleApplyCoupon = (coupon) => {
    const subtotal = calculateTotals().subtotal;
    const minAmt = parseFloat(coupon.applicable_order_amt || coupon.min_order_amount || 0);
    if (subtotal < minAmt) {
      toast.error('Coupon requires minimum spend of Rs ' + minAmt.toFixed(2));
      return;
    }
    setAppliedCoupon(coupon);
    setCouponCode(coupon.coupon_code || coupon.code);
    toast.success('Coupon ' + (coupon.coupon_code || coupon.code) + ' applied successfully!');
    setIsCouponModalOpen(false);
  };

  const handleRemoveCoupon = () => {
    setAppliedCoupon(null);
    setCouponCode('');
    toast.info("Coupon removed.");
  };

  const handleOpenCouponModal = async () => {
    setIsCouponModalOpen(true);
    try {
      const res = await posService.getCoupons(posSettings.outletId);
      setAvailableCoupons(res.data || []);
    } catch (err) {
      console.error("Failed to fetch coupons:", err);
      setAvailableCoupons([]);
    }
  };"
